import{_ as t,o as e,c as s,a0 as r}from"./chunks/framework.BpJS36ta.js";const h=JSON.parse('{"title":"Crypto Module","description":"","frontmatter":{},"headers":[],"relativePath":"modules/syntax/crypto.md","filePath":"modules/syntax/crypto.md"}'),n={name:"modules/syntax/crypto.md"};function o(d,a,p,c,i,l){return e(),s("div",null,[...a[0]||(a[0]=[r(`<h1 id="crypto-module" tabindex="-1">Crypto Module <a class="header-anchor" href="#crypto-module" aria-label="Permalink to &quot;Crypto Module&quot;">​</a></h1><p>Module <code>crypto</code> menyediakan fungsi hashing dan encoding.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>import crypto from rupa</span></span></code></pre></div><h2 id="fungsi" tabindex="-1">Fungsi <a class="header-anchor" href="#fungsi" aria-label="Permalink to &quot;Fungsi&quot;">​</a></h2><h3 id="crypto-hash-str" tabindex="-1">crypto.hash(str) <a class="header-anchor" href="#crypto-hash-str" aria-label="Permalink to &quot;crypto.hash(str)&quot;">​</a></h3><p>Hash string menggunakan DJB2 (non-cryptographic, sangat cepat).</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.hash(&quot;hello&quot;))  // 310f923099</span></span></code></pre></div><h3 id="crypto-fnv1a-str" tabindex="-1">crypto.fnv1a(str) <a class="header-anchor" href="#crypto-fnv1a-str" aria-label="Permalink to &quot;crypto.fnv1a(str)&quot;">​</a></h3><p>Hash string menggunakan FNV-1a.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.fnv1a(&quot;hello&quot;))  // a430d84680aabd0b</span></span></code></pre></div><h3 id="crypto-murmur3-str-seed" tabindex="-1">crypto.murmur3(str, seed?) <a class="header-anchor" href="#crypto-murmur3-str-seed" aria-label="Permalink to &quot;crypto.murmur3(str, seed?)&quot;">​</a></h3><p>Hash string menggunakan MurmurHash3.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.murmur3(&quot;hello&quot;))     // 248bfa47</span></span>
<span class="line"><span>print(crypto.murmur3(&quot;hello&quot;, 42)) // hash dengan seed</span></span></code></pre></div><h3 id="crypto-xor-str-key" tabindex="-1">crypto.xor(str, key) <a class="header-anchor" href="#crypto-xor-str-key" aria-label="Permalink to &quot;crypto.xor(str, key)&quot;">​</a></h3><p>XOR cipher — encrypt/decrypt dengan key yang sama.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>encrypted = crypto.xor(&quot;secret&quot;, &quot;key&quot;)</span></span>
<span class="line"><span>decrypted = crypto.xor(encrypted, &quot;key&quot;)</span></span>
<span class="line"><span>print(decrypted)  // secret</span></span></code></pre></div><h3 id="crypto-base64encode-str" tabindex="-1">crypto.base64Encode(str) <a class="header-anchor" href="#crypto-base64encode-str" aria-label="Permalink to &quot;crypto.base64Encode(str)&quot;">​</a></h3><p>Encode string ke Base64.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>encoded = crypto.base64Encode(&quot;Hello Rupa!&quot;)</span></span>
<span class="line"><span>print(encoded)  // SGVsbG8gUnVwYSEA</span></span></code></pre></div><h3 id="crypto-base64decode-str" tabindex="-1">crypto.base64Decode(str) <a class="header-anchor" href="#crypto-base64decode-str" aria-label="Permalink to &quot;crypto.base64Decode(str)&quot;">​</a></h3><p>Decode Base64 ke string.</p><div class="language-rupa vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">rupa</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>print(crypto.base64Decode(&quot;SGVsbG8gUnVwYSEA&quot;))  // Hello Rupa!</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Fungsi</th><th>Parameter</th><th>Return</th></tr></thead><tbody><tr><td><code>hash(str)</code></td><td>string</td><td>string</td></tr><tr><td><code>fnv1a(str)</code></td><td>string</td><td>string</td></tr><tr><td><code>murmur3(str, seed?)</code></td><td>string, number?</td><td>string</td></tr><tr><td><code>xor(str, key)</code></td><td>dua string</td><td>string</td></tr><tr><td><code>base64Encode(str)</code></td><td>string</td><td>string</td></tr><tr><td><code>base64Decode(str)</code></td><td>string</td><td>string</td></tr></tbody></table><h2 id="catatan" tabindex="-1">Catatan <a class="header-anchor" href="#catatan" aria-label="Permalink to &quot;Catatan&quot;">​</a></h2><ul><li><code>hash</code>, <code>fnv1a</code>, <code>murmur3</code> adalah hash non-cryptographic untuk dedup/checksum.</li><li><code>xor</code> adalah XOR cipher sederhana — untuk enkripsi ringan, bukan keamanan.</li><li><code>base64Encode</code>/<code>base64Decode</code> untuk encoding data.</li></ul>`,25)])])}const g=t(n,[["render",o]]);export{h as __pageData,g as default};
